// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;

const text = (typeof csvRaw === 'string')
  ? csvRaw
  : JSON.stringify(csvRaw);

const lines = text
  .split(/\r?\n/)
  .map(l => l.trim())
  .filter(Boolean);

const headers = lines[0].split(';').map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(';').map(c => c.trim());
  const obj = {};

  headers.forEach((h, i) => {
    obj[h] = cols[i] ?? '';
  });

  // normaliza tipo numérico
  obj['mínimo'] = Number(
    String(obj['mínimo']).replace(/[^\d,.-]/g, '').replace(',', '.')
  );

  return obj;
});

return [{ json: { investimentos } }];

// Code2 – integra os dados do cliente (Webhook) com os investimentos (CSV)
const item = $input.first().json;

// Dados do cliente enviados no POST
const cliente = item.body ?? {};

// Lista de investimentos vinda do nó "Code in JavaScript"
const investimentos = Array.isArray(item.investimentos) ? item.investimentos : [];

// Valor disponível do cliente (tenta nomes comuns de campo)
const valorKeys = ['valor', 'valorDisponivel', 'valor_disponivel', 'aporte', 'patrimonio'];
let valorCliente = null;
for (const k of valorKeys) {
  if (cliente[k] !== undefined && cliente[k] !== '') {
    valorCliente = Number(String(cliente[k]).replace(/[^\d,.-]/g, '').replace(',', '.'));
    break;
  }
}

// Perfil do cliente (opcional)
const perfil = String(cliente.perfil ?? cliente.perfilInvestidor ?? '')
  .trim()
  .toLowerCase();

// Filtra investimentos compatíveis
const recomendados = investimentos.filter(inv => {
  const minimo = Number(inv['mínimo']);
  const okValor = valorCliente === null || isNaN(minimo) || minimo <= valorCliente;

  const risco = String(inv['risco'] ?? '').toLowerCase();
  const okPerfil = !perfil || !risco || risco.includes(perfil) || perfil.includes(risco);

  return okValor && okPerfil;
});

// Resultado integrado
return [{
  json: {
    cliente,
    valorCliente,
    perfil: perfil || null,
    totalInvestimentos: investimentos.length,
    totalRecomendados: recomendados.length,
    recomendados,
    investimentos,
    processadoEm: new Date().toISOString()
  }
}];

// code3 – normaliza e organiza o resultado: 1 item por cliente, com produtos recomendados

const src = $input.first().json;

// ---------- helpers ----------
const semAcento = (s) =>
  String(s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().toLowerCase();

const capitalizar = (s) =>
  String(s ?? '').trim().toLowerCase().replace(/(^|\s)\S/g, (c) => c.toUpperCase());

// "R$ 12.500,00" -> 12500 | "1000" -> 1000 | "6.2%" -> 6.2
const paraNumero = (v) => {
  if (typeof v === 'number') return v;
  let s = String(v ?? '').replace(/[^\d,.-]/g, '');
  if (!s) return null;
  if (s.includes(',')) s = s.replace(/\./g, '').replace(',', '.');
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
};

const brl = (n) =>
  n === null || n === undefined
    ? null
    : n.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

// ---------- clientes ----------
let clientesRaw =
  src.cliente?.clientes ?? src.clientes ?? src.body?.clientes ?? src.cliente ?? [];
if (!Array.isArray(clientesRaw)) clientesRaw = [clientesRaw];

const clientes = clientesRaw.map((c) => {
  const saldo = paraNumero(c.saldo ?? c.valor ?? c.valorDisponivel);
  return {
    nome: String(c.nome ?? '').trim(),
    email: String(c.email ?? '').trim().toLowerCase(),
    perfil: capitalizar(c.perfil),
    saldo,
  };
});

// ---------- investimentos ----------
const investimentosRaw = Array.isArray(src.investimentos) ? src.investimentos : [];

const investimentos = investimentosRaw
  .map((inv) => {
    // Caso o CSV tenha vindo "colado" numa única coluna (separador errado)
    const chaves = Object.keys(inv);
    if (chaves.length && chaves[0].includes(',')) {
      const cab = chaves[0].split(',').map((h) => semAcento(h));
      const val = String(inv[chaves[0]]).split(',').map((v) => v.trim());
      inv = Object.fromEntries(cab.map((h, i) => [h, val[i] ?? '']));
    } else {
      inv = Object.fromEntries(chaves.map((k) => [semAcento(k), inv[k]]));
    }
    return {
      perfil: capitalizar(inv.perfil),
      produto: String(inv.produto ?? '').trim(),
      minimo: paraNumero(inv.minimo),
      rentabilidade: String(inv.rentabilidade ?? '').trim(),
    };
  })
  .filter((i) => i.produto);

// ---------- cruzamento cliente x produto ----------
const processadoEm = src.processadoEm ?? new Date().toISOString();

const saida = clientes.map((cli) => {
  const recomendados = investimentos
    .filter(
      (inv) =>
        semAcento(inv.perfil) === semAcento(cli.perfil) &&
        (inv.minimo === null || cli.saldo === null || inv.minimo <= cli.saldo)
    )
    .map((inv) => ({
      produto: inv.produto,
      minimo: brl(inv.minimo),
      rentabilidade: inv.rentabilidade,
    }));

  return {
    json: {
      nome: cli.nome,
      email: cli.email,
      perfil: cli.perfil,
      saldo: brl(cli.saldo),
      saldoNumerico: cli.saldo,
      totalRecomendados: recomendados.length,
      recomendados,
      resumo: recomendados.length
        ? recomendados.map((r) => `${r.produto} (${r.rentabilidade})`).join(' | ')
        : 'Nenhum produto compatível com o saldo/perfil',
      processadoEm,
    },
  };
});

return saida;

