// Code4 – normaliza a resposta do modelo e gera 1 item por cliente, pronto para envio

const itens = $input.all();
const clientes = $('code3').all(); // mesma ordem dos itens do modelo

// Extrai o texto da resposta, aceitando os formatos mais comuns da OpenAI
const extrairTexto = (j) => {
  if (typeof j.output_text === 'string') return j.output_text;
  if (typeof j.text === 'string') return j.text;
  if (typeof j.message?.content === 'string') return j.message.content;
  if (Array.isArray(j.output)) {
    return j.output
      .flatMap((o) => (Array.isArray(o.content) ? o.content : []))
      .filter((c) => c.type === 'output_text' || typeof c.text === 'string')
      .map((c) => c.text)
      .join('\n');
  }
  return '';
};

// Limpa quebras de linha, espaços repetidos e marcação markdown
const limpar = (s) =>
  String(s ?? '')
    .replace(/\r\n/g, '\n')
    .replace(/\*\*/g, '')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

return itens.map((item, i) => {
  const cli = clientes[i]?.json ?? {};
  let corpo = limpar(extrairTexto(item.json));

  // Separa o assunto (se existir) do corpo do e-mail
  let assunto = `Sugestão de investimentos para ${cli.nome || 'você'}`;
  const m = corpo.match(/^assunto:\s*(.+)\n?/i);
  if (m) {
    assunto = m[1].trim();
    corpo = corpo.replace(m[0], '').trim();
  }

  return {
    json: {
      nome: cli.nome ?? null,
      email: cli.email ?? null,
      perfil: cli.perfil ?? null,
      saldo: cli.saldo ?? null,
      produtosRecomendados: cli.recomendados ?? [],
      email_assunto: assunto,
      email_corpo: corpo,
      email_html: corpo.replace(/\n/g, '<br>'),
      status: corpo ? 'pronto_para_envio' : 'sem_texto_gerado',
      geradoEm: new Date().toISOString(),
    },
  };
});
